// Render translates markdown to HTML.
//
// The implementation works line by line. Each line is classified as one of
// three block types:
//
//   - a heading: 1-6 '#' characters followed by a space, e.g. "## Title"
//   - a list item: a '*' followed by a space, e.g. "* Item"
//   - a paragraph: anything else
//
// Consecutive list items are grouped in a single <ul> element.
// Inline emphasis is then applied: "__bold__" becomes <strong> and
// "_italic_" becomes <em>.
func Render(markdown string) string {
	var b strings.Builder
	inList := false

	for _, line := range strings.Split(markdown, "\n") {
		if inList && !isListItem(line) {
			b.WriteString("</ul>")
			inList = false
