			fmt.Fprintf(&b, "<h%d>%s</h%d>", level, emphasize(title), level)
		case isListItem(line):
			if !inList {
				b.WriteString("<ul>")
				inList = true
			}
			b.WriteString("<li>" + emphasize(line[len("* "):]) + "</li>")
		default:
			b.WriteString("<p>" + emphasize(line) + "</p>")
		}
	}

	if inList {
		b.WriteString("</ul>")
	}

	return b.String()
}
```

